def localize(body: str) -> str:
    for en, es in sorted(TEXT.items(), key=lambda kv: -len(kv[0])):
        body = body.replace('>' + en + '<', '>' + es + '<')
    for en, es in RAW:
        body = body.replace(en, es)
    return body
